const fs = require('fs');
const path = require('path');

const OUT = path.join(__dirname, '..', '..', '06-Implementation', 'platforms', 'react', 'src');

const TAG_MAP = {
  overlay: 'div', backdrop: 'div', container: 'div', panel: 'div',
  header: 'div', body: 'div', footer: 'div',
  closeButton: 'button', formField: 'div', wrapper: 'div',
  label: 'label', input: 'input', select: 'select',
  helperText: 'span', errorText: 'span', button: 'button',
  toggle: 'input', link: 'a', icon: 'svg', spinner: 'span',
  tabList: 'div', tab: 'button', accordion: 'div',
  accordionItem: 'div', trigger: 'button', content: 'div',
  menu: 'div', menuItem: 'button', divider: 'hr', sectionLabel: 'span',
  notification: 'div', tooltip: 'div',
  dataTable: 'table', list: 'ul', badge: 'span', tag: 'span',
  avatar: 'div', progress: 'div', skeleton: 'div',
  timeline: 'div', statistic: 'div',
  navigation: 'nav', breadcrumb: 'nav', pagination: 'nav', stepper: 'div',
  media: 'img', element: 'div'
};

function renderNode(n, depth) {
  const ind = '  '.repeat(depth);
  if (!n) return '';

  if (n.type === 'slot') return `${ind}{${n.props?.propName || 'children'}}`;
  if (n.type === 'text') return `${ind}"${(n.props?.value || '').replace(/×/g, '\\u00d7')}"`;

  const tag = TAG_MAP[n.type] || 'div';
  const props = n.props || {};
  const parts = [];

  if (props.className) parts.push(`className="${props.className}"`);
  if (props.role) parts.push(`role="${props.role}"`);
  for (const [k, v] of Object.entries(props)) {
    if (k.startsWith('aria-')) parts.push(`${k}="${v}"`);
    if (k.startsWith('data-')) parts.push(`${k}="${v}"`);
  }

  if (n.type === 'closeButton') parts.push('onClick={onClose}');

  if (n.type === 'input' && props.multiline) {
    delete props.multiline;
  }

  const attrStr = parts.length ? ' ' + parts.join(' ') : '';

  const children = (n.children || []).map(c => renderNode(c, depth + 1)).filter(Boolean);
  const childrenStr = children.length ? '\n' + children.join('\n') + '\n' + ind : '';
  const blockTags = ['div', 'span', 'p', 'section', 'header', 'footer', 'main', 'nav', 'form', 'article', 'aside', 'ul', 'ol', 'li', 'table', 'thead', 'tbody', 'tr', 'td', 'th', 'label', 'select', 'textarea', 'a', 'button', 'svg', 'img', 'hr'];

  let el;
  if (blockTags.includes(tag) || children.length) {
    el = `<${tag}${attrStr}>${childrenStr}</${tag}>`;
  } else {
    el = `<${tag}${attrStr} />`;
  }

  if (props.conditional) return `{open && (\n${ind}  ${el}\n${ind})}`;
  return `${ind}${el}`;
}

function renderReact(ir) {
  const { component, meta, tree } = ir;
  const isOverlay = meta.isOverlay;
  const slotNames = meta.slots.map(s => s.propName).filter(Boolean).join(', ');
  const overlayProps = isOverlay ? 'open, onClose' : '';
  const allProps = [overlayProps, slotNames].filter(Boolean).join(', ');

  const imports = isOverlay
    ? "import React, { useEffect, useRef, useCallback } from 'react';"
    : "import React from 'react';";

  const hooks = isOverlay ? `
  const dialogRef = useRef(null);

  useEffect(() => {
    if (!open) return;
    const el = dialogRef.current;
    if (!el) return;
    const focusable = el.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    focusable?.[0]?.focus();
    const handler = (e) => { if (e.key === 'Escape') onClose?.(); };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [open, onClose]);
` : '';

  const compName = component.name.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join('');
  const body = renderNode(tree, 2);

  return `// Generated from canonical reference
// Component: ${component.id}
// Auto-generated by AEL Compiler (React Renderer) — DO NOT EDIT
// Source: AEL Compiler IR v${ir.version}

${imports}

export function ${compName}({ ${allProps || '...props'} }) {${hooks}
  return (
${body}
  );
}
`;
}

module.exports = { renderReact };
